-- Fixes the Winter 2026-27 Rec players import (2026-11-07-rec-players-import.sql):
-- everyone 3rd grade and up was loaded with team = 'Unassigned', which the Draft
-- Board doesn't match against (it looks for the exact team name, e.g. '3/4 Boys'),
-- and division = '-', which doesn't match 'Winter Rec' either. Safe to run even
-- though these rows already exist -- it's the same on-conflict-update pattern.

on conflict (id) do update set
  number = excluded.number, name = excluded.name, grade = excluded.grade, school = excluded.school,
  guardian = excluded.guardian, phone = excluded.phone, position = excluded.position, status = excluded.status,
  waiver = excluded.waiver, program = excluded.program, division = excluded.division, team = excluded.team;
